"""Analyze microburst snapshot sequence: locate regions and byte ranges that change.

Usage: python mbdiff.py <dir> <tag> [n]
"""
import sys, json
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")
wdir = ROOT / sys.argv[1] if not sys.argv[1].startswith('_work') else ROOT / sys.argv[1]
tag = sys.argv[2]
n = int(sys.argv[3]) if len(sys.argv) > 3 else 40

def load(i):
    p = wdir / f'{tag}.m{i}'
    if not p.exists():
        return None
    d = p.read_bytes()
    idx = json.loads((wdir / f'{tag}.m{i}.idx.json').read_text())
    return d, idx

def regions_map(idx):
    return {r['addr']: r for r in idx}

snaps = {}
for i in range(n):
    s = load(i)
    if s:
        snaps[i] = s
keys = sorted(snaps)
print('snapshots:', keys[:5], '...', keys[-3:])
prev = None
for i in keys:
    d, idx = snaps[i]
    if prev is None:
        prev = (d, idx)
        print(f'--- snap {i}: {len(idx)} regions, {len(d)} bytes')
        for r in idx:
            print(f'    addr={r["addr"]:#x} size={r["size"]}')
        continue
    pd, pidx = prev
    pm = regions_map(pidx)
    changes = []
    for r in idx:
        if r['addr'] in pm:
            pr = pm[r['addr']]
            common = min(r['size'], pr['size'])
            a = pd[pr['off']:pr['off']+common]
            b = d[r['off']:r['off']+common]
            if a != b:
                # find changed ranges
                rngs = []
                st = None
                for k in range(common):
                    if a[k] != b[k]:
                        if st is None:
                            st = k
                        lst = k
                    elif st is not None and k - lst > 64:
                        rngs.append((st, lst))
                        st = None
                if st is not None:
                    rngs.append((st, lst))
                changes.append((r['addr'], common, rngs[:6]))
        else:
            changes.append((r['addr'], r['size'], 'NEW'))
    print(f'--- snap {i} vs {i-1}: {len(changes)} changed/new regions')
    for addr, size, rngs in changes:
        if rngs == 'NEW':
            print(f'    NEW addr={addr:#x} size={size}')
        else:
            print(f'    addr={addr:#x} size={size} changed-ranges={[(hex(x), hex(y)) for x, y in rngs]}')
    prev = (d, idx)
